const palettes={sales:'client_call',bd:'bd_partner',design:'brand_studio',project:'project_schedule',product:'meeting',finance:'finance_budget',accounting:'accounting',hr:'recruiting',admin:'admin_coffee',executive:'meeting'};
const tones=[
 [{skill:8,trust:6,energy:-6,mood:3,boss:-2},{lick:7,trust:-4,energy:-7,mood:-5,boss:5},{slack:7,trust:4,energy:-4,mood:6,boss:-4}],
 [{skill:7,trust:5,energy:-5,mood:4,boss:-3},{lick:6,trust:-5,energy:-6,mood:-6,boss:6},{slack:8,trust:3,energy:-5,mood:7,boss:-5}],
 [{skill:8,trust:4,energy:-7,mood:2,boss:-2},{lick:8,trust:-3,energy:-7,mood:-5,boss:6},{slack:6,trust:5,energy:-4,mood:6,boss:-3}]
];
export function careerScenesV71(data=work){return Object.entries(data).flatMap(([role,rows])=>rows.map(([slug,title,speaker,body,wing,...answers],index)=>({
 id:`career71-${role}-${slug}`,title,speaker,body,wing,roles:[role],scene:palettes[role]||'office_day',kind:'daily',minRules:39,minTurn:0,weight:2.6,requiresCareerV71:true,careerFocusV71:true,era:'原創・各憑本事上班',sourceIds:['careerFictionV71','characterFiction'],
 choices:answers.map(([text,result],at)=>({text,detail:'',result,delta:{...tones[index%tones.length][at],...(role==='sales'&&slug==='discount-ceiling'&&at===1?{cash:-8}:{})},flags:[`career71_${role}`,at===0?'evidence':at===1?'loop':'archive'],...(at===2?{wild:true}:{})})),
 verbalLinesV71:[`幹，${answers[0][0].replace(/。$/,'')}，這件事就有得談。別把剛才沒確認的東西全塞給做事的人，然後一句大家想辦法就當你已經負責。`,`靠北，剛才說的就是「${title.replace(/[。！]/g,'')}」這一件。把原本答應的條件留著，別事情一難看又裝成從來沒人問過。`]
})));}
export const CAREER_EVENTS_V71=Object.freeze(careerScenesV71());
